/**
 * @file TableWriter.mjs
 * @brief Writes generated data tables as ES modules with a "do not edit" header.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

/** Project root (two levels above tools/data). */
export const PROJECT_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..');

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;
const key = (name) => (IDENTIFIER.test(name) ? name : JSON.stringify(name));

/**
 * Compact one-line rendering: unquoted identifier keys, spaces after commas.
 * @param {*} value
 * @returns {string}
 */
export function inline(value) {
  if (Array.isArray(value)) return `[${value.map(inline).join(', ')}]`;
  if (value && typeof value === 'object') {
    const body = Object.entries(value).map(([name, item]) => `${key(name)}: ${inline(item)}`).join(', ');
    return body ? `{ ${body} }` : '{}';
  }
  return JSON.stringify(value);
}

/**
 * Writes `export const <name> = { id: {...}, ... };` (or an array) and returns the entry count.
 * @param {Object} options
 * @param {string} options.file - Path relative to the project root
 * @param {string} options.name - Exported constant
 * @param {string} options.brief - One-line description
 * @param {string[]} [options.notes=[]] - Extra header lines (format of an entry…)
 * @param {Object|Array} options.data
 * @param {string} options.generator - Script that produced the file
 * @returns {number}
 */
export function writeTable({ file, name, brief, notes = [], data, generator }) {
  const isArray = Array.isArray(data);
  const entries = isArray
    ? data.map((entry) => `  ${inline(entry)},`)
    : Object.entries(data).map(([id, entry]) => `  ${key(id)}: ${inline(entry)},`);
  const header = [
    '/**',
    ` * @file ${path.basename(file)}`,
    ` * @brief ${brief}`,
    ` * GENERATED by ${generator} from the original game data. Do not edit by hand.`,
    ...notes.map((line) => (line ? ` * ${line}` : ' *')),
    ' */',
    ''
  ].join('\n');
  const body = `export const ${name} = ${isArray ? '[' : '{'}\n${entries.join('\n')}\n${isArray ? ']' : '}'};\n`;
  const target = path.join(PROJECT_ROOT, file);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, header + body);
  return entries.length;
}
